/* @lc app=leetcode id=2306 lang=kotlin */
class Solution { fun distinctNames(ideas: Array<String>): Long = Array(26) { mutableSetOf<String>() }.apply { ideas.forEach { this[it[0] - 'a'].add(it.substring(1)) } }.let { sets -> sets.indices.sumOf { i -> (i + 1 until 26).sumOf { j -> sets[i].count { it in sets[j] }.toLong().let { common -> (sets[i].size - common) * (sets[j].size - common) * 2 } } } } }